function normalizeGraphicsMode(mode){return mode==='classic'||mode==='textured'||mode==='beauty'||mode==='minimal'||mode==='newstyle'?mode:'textured';}
function _getUserGraphicsMode(){return normalizeGraphicsMode(gameSettings&&gameSettings.graphicsMode||((gameSettings&&gameSettings.texturedTerrain===false)?'classic':'textured'));}
function getGraphicsMode(){if(_adaptiveQuality&&_adaptiveQuality.active&&_adaptiveQuality.overrideMode){var user=_getUserGraphicsMode();var fb=_adaptiveQuality.overrideMode;var order=['classic','minimal','textured','newstyle','beauty'];var ui=order.indexOf(user),fi=order.indexOf(fb);if(fi>=0&&fi<ui)return fb;return user;}return _getUserGraphicsMode();}
function syncLegacyGraphicsFlag(){if(gameSettings)gameSettings.texturedTerrain=_getUserGraphicsMode()!=='classic';}
function isBeautyGraphicsMode(){return getGraphicsMode()==='beauty';}
function isMinimalGraphicsMode(){return getGraphicsMode()==='minimal';}
function isNewStyleGraphicsMode(){return getGraphicsMode()==='newstyle';}
function loadGameSettings(){try{const raw=localStorage.getItem(SETTINGS_STORAGE_KEY);if(!raw){if(gameSettings&&!gameSettings.graphicsMode)gameSettings.graphicsMode=gameSettings.texturedTerrain===false?'classic':'textured';syncLegacyGraphicsFlag();return;}const parsed=JSON.parse(raw);if(parsed&&typeof parsed==='object'){if(typeof parsed.graphicsMode==='string')gameSettings.graphicsMode=normalizeGraphicsMode(parsed.graphicsMode);else if(typeof parsed.texturedTerrain==='boolean')gameSettings.graphicsMode=parsed.texturedTerrain?'textured':'classic';}}catch(err){console.warn('Settings load failed:',err);}if(gameSettings&&!gameSettings.graphicsMode)gameSettings.graphicsMode=gameSettings.texturedTerrain===false?'classic':'textured';syncLegacyGraphicsFlag();}
function saveGameSettings(){try{syncLegacyGraphicsFlag();localStorage.setItem(SETTINGS_STORAGE_KEY,JSON.stringify({texturedTerrain:!!gameSettings.texturedTerrain,graphicsMode:getGraphicsMode()}));}catch(err){console.warn('Settings save failed:',err);}}
function updateTextureModeUi(){const mode=getGraphicsMode();document.querySelectorAll('[data-graphics-mode]').forEach(btn=>{const active=btn.dataset.graphicsMode===mode;btn.classList.toggle('active',active);btn.setAttribute('aria-pressed',active?'true':'false');});const note=document.getElementById('graphics-mode-note');if(note){if(mode==='classic')note.innerHTML='<b>Klasická:</b> původní jednoduchá kresba s minimem detailů.';else if(mode==='textured')note.innerHTML='<b>Textury:</b> současný texturovaný terén a standardní 2D jednotky.';else if(mode==='minimal')note.innerHTML='<b>Minimalistický:</b> absolutní priorita výkonu, čisté tvary, minimum efektů a maximální čitelnost jednotek.';else if(mode==='newstyle')note.innerHTML='<b>New Style:</b> kompletně přepracované všechny jednotky i budovy, moderní ostrý sci-fi styl od nuly a střední HW náročnost.';else note.innerHTML='<b>Nejkrásnější grafika:</b> předrender cache pro stabilní výkon, propracovanější jednotky a budovy, jemnější návaznost dlaždic, lepší vodu i detailnější terén bez zásahu do herní logiky.';}}
function setGraphicsMode(mode){const next=normalizeGraphicsMode(mode);if(getGraphicsMode()===next){updateTextureModeUi();return;}gameSettings.graphicsMode=next;syncLegacyGraphicsFlag();saveGameSettings();updateTextureModeUi();invalidateTerrainCaches();}
function setTexturedTerrain(enabled){setGraphicsMode(enabled?'textured':'classic');}
function initSettingsUi(){loadGameSettings();updateTextureModeUi();document.querySelectorAll('[data-graphics-mode]').forEach(btn=>{if(btn.dataset.bound)return;btn.dataset.bound='1';const craneBtn=document.getElementById('btn-crane');if(craneBtn)craneBtn.style.display='none';const stationBtn=document.getElementById('btn-train');if(stationBtn)stationBtn.title='Nádraží';btn.addEventListener('click',()=>setGraphicsMode(btn.dataset.graphicsMode));});}


